// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        vm.assume(amount1 > 0 && amount2 > 0 && amount1 <= 1e30 && amount2 <= 1e30);

        // Mint some tokens to addr1 and addr2 via transfer to simulate balance changes
        // We'll use transfer to move tokens into the contract itself (which burns later)
        // Since contract has no ETH, we just do dummy operations that don't revert
        // The key is that allowance is a view function that doesn't change state

        // Read totalSupply before
        uint256 totalBefore = c.totalSupply();

        // Call allowance (this is the differing entry point per the problem statement)
        c.allowance(addr1, addr2);

        // After allowance, totalSupply should still match sum of all balances
        // Since we didn't mint/burn, totalSupply should equal sum of balances
        // We can only read balances via balanceOf, which is public

        // Compute sum of balances for two addresses and zero address
        uint256 sumBalances = c.balanceOf(addr1) + c.balanceOf(addr2) + c.balanceOf(address(0)) + c.balanceOf(address(c));

        // Also include the contract deployer (address(this) from setUp) and msg.sender
        sumBalances += c.balanceOf(address(this));

        // The invariant: totalSupply == sum of all balances of all addresses
        // We approximate with a subset: totalSupply should equal at least the sum of these
        // But to be a general rule that holds, we assert that totalSupply does not decrease below sumBalances
        // Since the bug removes totalSupply decrease on burn, the buggy version keeps totalSupply higher
        // So the rule is: totalSupply >= sumBalances (always true for correct version, but buggy version may have totalSupply > sumBalances after burn)

        assertTrue(c.totalSupply() >= sumBalances);
    }
}

