// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1e30);
        vm.assume(account != address(0));

        // Mint some tokens to create a balance
        c.mintSynth(account, amount);

        // Burn some tokens from the contract
        c.burn(amount);

        // Call allowance to trigger the bug (reading state doesn't change anything)
        c.allowance(address(this), account);

        // After the calls, totalSupply must equal the sum of balances of the contract and the caller (address(this))
        uint256 totalSupply = c.totalSupply();
        uint256 contractBalance = c.balanceOf(address(this));
        uint256 callerBalance = c.balanceOf(address(this));
        assertTrue(totalSupply == contractBalance + callerBalance);
    }
}

