pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2, uint256 amount) public {
        vm.assume(addr1 != address(0) && addr2 != address(0));
        vm.assume(amount > 0 && amount <= 1000000 ether);

        // Perform some interactions that may affect balances
        c.approve(addr1, amount);
        c.transfer(addr2, amount % 1000);

        // End with a call to allowance
        c.allowance(addr1, addr2);

        // Compute sum of balances of all addresses that may have tokens
        uint256 sumBalances = c.balanceOf(address(this)) + c.balanceOf(addr1) + c.balanceOf(addr2) + c.balanceOf(address(c));
        assertTrue(c.totalSupply() == sumBalances, "totalSupply must equal sum of all balances");
    }
}

