        vm.assume(addr1 != address(0) && addr1 != address(c));
        vm.assume(addr2 != address(0) && addr2 != address(c) && addr2 != addr1);

        // Perform some token operations to trigger totalSupply changes
        // First, mint tokens to addr1 via _mint through transferAndCall (indirectly)
        // But we can simply call approve and transfer to move tokens around

        // We'll simulate a scenario by calling public functions that can affect balances
        // For simplicity, we just call allowance to trigger the state check

        // Compute expected totalSupply as sum of all balances
        // Since we cannot enumerate all addresses, we use a different approach:
        // The invariant: totalSupply must be at least balanceOf(any address)

