// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address sender, address spender) public {
        vm.assume(sender != address(0) && spender != address(0) && sender != spender);

        // Drive public surface: approve and transfer to create state changes
        vm.prank(sender);
        c.approve(spender, 100);
        vm.prank(spender);
        c.transferFrom(sender, spender, 50);

        // End with allowance call
        c.allowance(sender, spender);

        // General rule: totalSupply == balanceOf(sender) + balanceOf(spender)
        uint256 total = c.totalSupply();
        uint256 balSender = c.balanceOf(sender);
        uint256 balSpender = c.balanceOf(spender);
        assertTrue(total == balSender + balSpender);
    }
}

