import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address owner, address spender, uint256 amount, uint8 op) public {
        // Bound inputs to avoid overflow/underflow in calls
        owner = bound(owner, 1, type(uint160).max);
        spender = bound(spender, 1, type(uint160).max);
        // Record totalSupply before any operation
        uint256 supplyBefore = c.totalSupply();
        // Drive C through a simple call that does not change totalSupply in reference
        // Use op to choose between approve and transfer (both should not affect totalSupply)
        if (op % 2 == 0) {
            vm.prank(owner);
            c.approve(spender, amount);
        } else {
            vm.prank(owner);
            // Use transfer with a small amount that respects balance
            uint256 ownerBal = c.balanceOf(owner);
            vm.assume(amount <= ownerBal);
            c.transfer(spender, amount);
        }
        // End with a call to allowance
        c.allowance(owner, spender);
        // Assert totalSupply unchanged
        assertTrue(c.totalSupply() == supplyBefore);
    }
}

