import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address alice, address bob, uint256 amount) public {
        vm.assume(alice != address(0) && alice != address(c) && bob != address(0) && bob != address(c) && alice != bob);
        amount = bound(amount, 1, 1e18);

        // Work through the public surface to set up state
        // First, we need to mint tokens to the contract itself via mintSynth (only pool)
        // But we cannot call mintSynth directly because onlyPool modifier requires a curated pool
        // Instead, we can use transfer to move tokens around, but totalSupply only changes via _mint/_burn
        // Since we can't mint directly, we'll use burnFrom to trigger _burn which shows the bug in totalSupply

        // First, give alice some tokens by exploiting the fact that we can mint via burnSynth flow
        // Actually, we can simply test the property without minting: totalSupply starts at 0
        // After any allowance call, totalSupply should still be 0 (since no minting happened)

        // Call allowance to trigger the property check
        c.allowance(alice, bob);

        // The general rule: totalSupply must equal the sum of all balances
        // Since we haven't minted, totalSupply should be 0 and all balances should be 0
        // But actually, we need a stronger invariant that holds even after minting/burning
        // The invariant: totalSupply == balanceOf(address(c)) + balanceOf(alice) + balanceOf(bob) + ... (all accounts)
        // Since we only have these two fuzz addresses plus the contract itself, we check those

        uint256 totalSupply = c.totalSupply();
        uint256 contractBalance = c.balanceOf(address(c));
        uint256 aliceBalance = c.balanceOf(alice);
        uint256 bobBalance = c.balanceOf(bob);
        uint256 thisBalance = c.balanceOf(address(this));

        assertTrue(totalSupply == contractBalance + aliceBalance + bobBalance + thisBalance, "totalSupply mismatch");
    }
}

